function setStatus(message, type = "info") {
  statusBox.className = "notice " + type;
  statusBox.textContent = message;
}

async function isAdmin(user) {
  if (!user) return false;
  const snap = await getDoc(doc(db, "users", user.uid));
  return snap.exists() && snap.data().role === "admin";
}

async function installBooks() {
  for (const item of BOOKS) {
    const { id, ...data } = item;
    await setDoc(doc(db, "books", id), { ...data, updatedAt: serverTimestamp() }, { merge: true });
  }
  return BOOKS.length;
}

async function installKiddies() {
  for (const item of KIDDIES) {
    const { id, ...data } = item;
    await setDoc(doc(db, "kiddiesResources", id), { ...data, updatedAt: serverTimestamp() }, { merge: true });
  }
  return KIDDIES.length;
}

async function installCourses() {
  let moduleCount = 0;
  let lessonCount = 0;
  for (const item of COURSES) {
    await setDoc(doc(db, "courses", item.id), { ...item.course, updatedAt: serverTimestamp() }, { merge: true });
    for (const module of item.modules) {
      const { id, ...moduleData } = module;
      await setDoc(doc(db, "courseModules", id), { ...moduleData, courseId: item.id, updatedAt: serverTimestamp() }, { merge: true });
      moduleCount++;
    }
    for (const lesson of item.lessons) {
      const { id, ...lessonData } = lesson;
      await setDoc(doc(db, "courseLessons", id), { ...lessonData, courseId: item.id, updatedAt: serverTimestamp() }, { merge: true });
      lessonCount++;
    }
  }
  return { courses: COURSES.length, modules: moduleCount, lessons: lessonCount };
}

async function runSeed() {
  if (!adminReady) throw new Error("Admin access not verified.");
  setStatus("Installing in-depth premium books...", "info");
  const books = await installBooks();
  setStatus("Installing in-depth Kiddies mini-books...", "info");
  const kiddies = await installKiddies();
  setStatus("Installing structured SpeakHub courses...", "info");
  const courseResult = await installCourses();
  return { books, kiddies, ...courseResult };
}

onAuthStateChanged(auth, async user => {
  if (!user) {
    setStatus("Please login as admin first, then refresh this page.", "error");
    seedBtn.disabled = true;
    return;
  }
  try {
    adminReady = await isAdmin(user);
    if (!adminReady) {
      setStatus("Access denied. Admin role required.", "error");
      seedBtn.disabled = true;
      return;
    }
    setStatus("Admin verified. You can install Premium V2 content.", "success");
    seedBtn.disabled = false;
  } catch (error) {
    console.error(error);
    setStatus("Admin check failed. " + (error.message || ""), "error");
  }
});

seedBtn.addEventListener("click", async () => {
  seedBtn.disabled = true;
  try {
    const result = await runSeed();
    setStatus(`Done.\n\nInstalled Premium V2 Content:\nBooks: ${result.books}\nKiddies: ${result.kiddies}\nCourses: ${result.courses}\nModules: ${result.modules}\nLessons: ${result.lessons}`, "success");
  } catch (error) {
    console.error(error);
    setStatus(error.message || "Premium V2 content seed failed.", "error");
    seedBtn.disabled = false;
  }
});
